-- The foreign key of `telegram_update`.`poll_answer_poll_id` referenced `poll_answer`.`poll_id`,
-- which is not a unique key. MySQL 8.4+ rejects such a key by default, so reference `poll`.`id` instead.
-- The constraint name is generated by the server, so look it up instead of assuming it.
SET @poll_answer_fk = (
    SELECT `CONSTRAINT_NAME`
    FROM `information_schema`.`KEY_COLUMN_USAGE`
    WHERE `TABLE_SCHEMA` = DATABASE()
      AND `TABLE_NAME` = 'telegram_update'
      AND `COLUMN_NAME` = 'poll_answer_poll_id'
      AND `REFERENCED_TABLE_NAME` = 'poll_answer'
    LIMIT 1
);
SET @poll_answer_fk_sql = IF(
    @poll_answer_fk IS NULL,
    'DO 0',
    CONCAT('ALTER TABLE `telegram_update` DROP FOREIGN KEY `', @poll_answer_fk, '`')
);
PREPARE poll_answer_fk_stmt FROM @poll_answer_fk_sql;
EXECUTE poll_answer_fk_stmt;
DEALLOCATE PREPARE poll_answer_fk_stmt;

SET @poll_fk = (
    SELECT COUNT(*)
    FROM `information_schema`.`KEY_COLUMN_USAGE`
    WHERE `TABLE_SCHEMA` = DATABASE()
      AND `TABLE_NAME` = 'telegram_update'
      AND `COLUMN_NAME` = 'poll_answer_poll_id'
      AND `REFERENCED_TABLE_NAME` = 'poll'
);
SET @poll_fk_sql = IF(
    @poll_fk > 0,
    'DO 0',
    'ALTER TABLE `telegram_update` ADD FOREIGN KEY (`poll_answer_poll_id`) REFERENCES `poll` (`id`)'
);
PREPARE poll_fk_stmt FROM @poll_fk_sql;
EXECUTE poll_fk_stmt;
DEALLOCATE PREPARE poll_fk_stmt;

-- Foreign keys on leftovers of older versions, which block deleting a referenced user.
-- The `botan_shortener` table (Botan.io integration, removed in 0.58.0) and the `message`.`new_chat_member`
-- column (replaced by `new_chat_members` in 0.45.0) are unused and kept as they are; drop them manually if wanted.
SET @botan_shortener_fk = (
    SELECT `CONSTRAINT_NAME`
    FROM `information_schema`.`KEY_COLUMN_USAGE`
    WHERE `TABLE_SCHEMA` = DATABASE()
      AND `TABLE_NAME` = 'botan_shortener'
      AND `COLUMN_NAME` = 'user_id'
      AND `REFERENCED_TABLE_NAME` IS NOT NULL
    LIMIT 1
);
SET @botan_shortener_fk_sql = IF(
    @botan_shortener_fk IS NULL,
    'DO 0',
    CONCAT('ALTER TABLE `botan_shortener` DROP FOREIGN KEY `', @botan_shortener_fk, '`')
);
PREPARE botan_shortener_fk_stmt FROM @botan_shortener_fk_sql;
EXECUTE botan_shortener_fk_stmt;
DEALLOCATE PREPARE botan_shortener_fk_stmt;

SET @new_chat_member_fk = (
    SELECT `CONSTRAINT_NAME`
    FROM `information_schema`.`KEY_COLUMN_USAGE`
    WHERE `TABLE_SCHEMA` = DATABASE()
      AND `TABLE_NAME` = 'message'
      AND `COLUMN_NAME` = 'new_chat_member'
      AND `REFERENCED_TABLE_NAME` IS NOT NULL
    LIMIT 1
);
SET @new_chat_member_fk_sql = IF(
    @new_chat_member_fk IS NULL,
    'DO 0',
    CONCAT('ALTER TABLE `message` DROP FOREIGN KEY `', @new_chat_member_fk, '`')
);
PREPARE new_chat_member_fk_stmt FROM @new_chat_member_fk_sql;
EXECUTE new_chat_member_fk_stmt;
DEALLOCATE PREPARE new_chat_member_fk_stmt;
